{"filepath": "rich/cells.py", "new_string": "def graphemes(text: str) -> Generator[str, None, None]:
    """Yield grapheme clusters from the text."""
    if not text:
        return

    import unicodedata

    current_grapheme = []
    prev_was_zwj = False

    for char in text:
        category = unicodedata.category(char)
        is_combining = category in ("Mn", "Mc", "Me")
        is_zwj = char == "\u200d"

        if not current_grapheme:
            current_grapheme.append(char)
        elif is_combining or is_zwj or prev_was_zwj:
            current_grapheme.append(char)
        else:
            yield "".join(current_grapheme)
            current_grapheme = [char]

        prev_was_zwj = is_zwj

    if current_grapheme:
        yield "".join(current_grapheme)


